// Paso 223 · v0.42.0 · Pantalla Operaciones societarias: patrimonio neto, constitución, ampliaciones, reparto, dividendos, pérdidas e historial
// Cambia solo los trozos necesarios (con unas líneas de contexto) y crea los ficheros nuevos.
// Uso (desde la carpeta frontend):   node aplicar-paso223-web.mjs
// Se puede ejecutar dos veces sin problema. Si algo no encaja, lo dice y no toca ese trozo.
import fs from 'node:fs'

const NEW_FILES = {
  "src/components/Equity.jsx": "import { useEffect, useState } from 'react'\nimport { supabase } from '../supabase'\nimport { useI18n } from '../i18n'\nimport { money, shortDate } from '../format'\nimport { companyPath } from '../router'\nimport { workDate } from '../workDate'\nimport { KINDS, PREVIEW_RPC, RPC, STATUS_ROWS, balanced, emptyForm, payload, previewEntries, undoable } from '../equity'\nimport Link from './Link'\nimport Sources from './Sources'\nimport ErrorBox from './ErrorBox'\n\n// OPERACIONES SOCIETARIAS (v0.42.0): el patrimonio neto de una sociedad y lo que la junta o el órgano de\n// administración acuerdan sobre él — constitución, ampliaciones, dividendos pasivos, reparto del resultado, dividendos\n// a cuenta y su pago, y pérdidas. La base de datos comprueba la LSC y contabiliza (0060 y 0061); aquí se elige la\n// operación, se ve el asiento antes y se contabiliza o se deshace (de la última a la primera).\n// En BC y SAP no hay pantalla equivalente: estas operaciones se registran con asientos manuales en el diario general.\nexport default function Equity({ company, readOnly }) {\n  const { t, language } = useI18n()\n  const [date, setDate] = useState(() => workDate(company))\n  const [status, setStatus] = useState(null)\n  const [ops, setOps] = useState([])\n  const [entryNos, setEntryNos] = useState({})   // id del asiento → [año, nº]\n  const [kind, setKind] = useState('distribution')\n  const [form, setForm] = useState(() => emptyForm('distribution', 'sl'))\n  const [prev, setPrev] = useState(null)         // vista previa del reparto o del dividendo a cuenta (la base de datos)\n  const [confirming, setConfirming] = useState(null)   // 'post' | id de la operación a deshacer\n  const [busy, setBusy] = useState(false)\n  const [error, setError] = useState('')\n  const [done, setDone] = useState(null)         // última operación contabilizada: { code, entry_nos }\n  const [refresh, setRefresh] = useState(0)\n  const m = (v) => money(v, language)\n  const canWrite = !readOnly\n\n  // Estado del patrimonio neto a la fecha e historial de operaciones\n  useEffect(() => {\n    let alive = true\n    Promise.all([\n      supabase.rpc('equity_status', { p_company: company.id, p_date: date }),\n      supabase.from('equity_operations').select('id, code, kind, op_date, description, status, entry_ids, result').eq('company_id', company.id).order('code', { ascending: false }),\n    ]).then(async ([s, o]) => {\n      if (!alive) return\n      if (s.error) return setError(s.error.code === 'PGRST202' ? t('eq.dbMissing') : s.error.message)\n      const list = o.data ?? []\n      const ids = list.flatMap((x) => x.entry_ids ?? [])\n      const { data: e } = ids.length\n        ? await supabase.from('journal_entries').select('id, entry_no, posting_date').in('id', ids)\n        : { data: [] }\n      if (!alive) return\n      setStatus(s.data); setOps(list)\n      setEntryNos(Object.fromEntries((e ?? []).map((x) => [x.id, [String(x.posting_date).slice(0, 4), x.entry_no]])))\n    })\n    return () => { alive = false }\n  }, [company.id, date, refresh])   // eslint-disable-line react-hooks/exhaustive-deps\n\n  // Vista previa del reparto o del dividendo a cuenta (la calcula la base de datos con la LSC)\n  useEffect(() => {\n    if (!PREVIEW_RPC[kind]) return undefined\n    let alive = true\n    supabase.rpc(PREVIEW_RPC[kind], { p: payload(kind, form, company.id, date) })\n      .then(({ data, error }) => { if (alive) setPrev(error ? null : data) })\n    return () => { alive = false }\n  }, [kind, form, date, company.id, refresh])\n\n  function choose(k) {\n    setKind(k); setForm(emptyForm(k, status?.legal_form)); setPrev(null); setConfirming(null); setDone(null); setError('')\n  }\n\n  async function post() {\n    setBusy(true); setError('')\n    const { data, error } = await supabase.rpc(RPC[kind], { p: payload(kind, form, company.id, date) })\n    setBusy(false); setConfirming(null)\n    if (error) return setError(error.message)\n    setDone(data); setForm(emptyForm(kind, status?.legal_form)); setRefresh((x) => x + 1)\n  }\n  async function undo(id) {\n    setBusy(true); setError('')\n    const { error } = await supabase.rpc('equity_cancel', { p_operation: id })\n    setBusy(false); setConfirming(null)\n    if (error) return setError(error.message)\n    setDone(null); setRefresh((x) => x + 1)\n  }\n  async function setLegalForm(f) {\n    setError('')\n    const { error } = await supabase.rpc('set_legal_form', { p_company: company.id, p_form: f })\n    if (error) return setError(error.message)\n    setRefresh((x) => x + 1)\n  }\n\n  const entries = previewEntries(kind, form, status ?? {}, prev)\n  const warnings = PREVIEW_RPC[kind] ? prev?.warnings ?? [] : []\n  const blocked = PREVIEW_RPC[kind] ? !prev?.ok : entries.length === 0\n  const lastId = undoable(ops)\n  const isAdmin = company.my_role === 'admin'\n  const field = (k, label, extra = {}) => (\n    <label>{label}\n      <input inputMode=\"decimal\" value={form[k] ?? ''} onChange={(e) => setForm({ ...form, [k]: e.target.value })} {...extra} />\n    </label>\n  )\n  const warnText = (w) => t(`eq.warn.${w.code}`).replace('{m}', m(w.min ?? w.interim ?? w.available ?? w.left ?? w.max ?? w.cash ?? w.net_worth_after ?? 0))\n    .replace('{c}', m(w.capital ?? 0))\n  const entryLink = (id) => {\n    const [y, n] = entryNos[id] ?? []\n    return n ? <Link key={id} className=\"enlace\" to={companyPath(company.id, `asiento/${y}/${n}`)}>{n}</Link> : null\n  }\n\n  return (\n    <>\n      <section className=\"tarjeta operaciones-societarias\">\n        <div className=\"titulo-modelo\"><h2>{t('eq.title')}</h2><Sources ids={['lsc', 'pgc']} /></div>\n        <p className=\"ayuda\">{t('eq.intro')}</p>\n        <div className=\"rejilla-tres\">\n          <label>{t('eq.date')}\n            <input type=\"date\" value={date} onChange={(e) => { setConfirming(null); setDate(e.target.value) }} />\n          </label>\n          <label>{t('eq.legalForm')}\n            <select value={status?.legal_form ?? 'sl'} disabled={!canWrite || !isAdmin || ops.some((o) => o.status === 'posted')}\n                    onChange={(e) => setLegalForm(e.target.value)}>\n              {['sl', 'sa'].map((f) => <option key={f} value={f}>{t(`eq.form.${f}`)}</option>)}\n            </select>\n          </label>\n        </div>\n        <p className=\"ayuda\">{t(ops.some((o) => o.status === 'posted') ? 'eq.legalFormLocked' : 'eq.legalFormHelp')}</p>\n        <ErrorBox error={error} company={company} />\n      </section>\n\n      {status && (\n        <section className=\"tarjeta\">\n          <h3>{t('eq.statusTitle').replace('{d}', shortDate(date))}</h3>\n          <div className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={t('eq.statusTitle').replace('{d}', '')}>\n            <table className=\"casillas\">\n              <tbody>\n                {STATUS_ROWS.filter(([k]) => Number(status[k]) !== 0 || ['capital', 'legal_reserve'].includes(k)).map(([k, s]) => (\n                  <tr key={k}><td>{t(`eq.st.${k}`)}</td><td className=\"num\">{s < 0 && Number(status[k]) ? '−' : ''}{m(status[k])}</td></tr>))}\n                <tr className=\"total\"><td>{t('eq.st.net_worth')}</td><td className=\"num\">{m(status.net_worth)}</td></tr>\n              </tbody>\n            </table>\n          </div>\n          <p className=\"ayuda\">\n            {t(status.low_capital_sl ? 'eq.reserveCapLow' : 'eq.reserveCap').replace('{m}', m(status.legal_reserve_cap))}\n            {Number(status.dividend_payable) > 0 && <> · {t('eq.st.dividend_payable')}: <strong>{m(status.dividend_payable)}</strong></>}\n            {Number(status.called_unpaid) > 0 && <> · {t('eq.st.called_unpaid')}: <strong>{m(status.called_unpaid)}</strong></>}\n          </p>\n          {Number(status.result_to_distribute) !== 0 && (\n            <p className=\"aviso-modo\">📌 {t('eq.pending').replace('{m}', m(status.result_to_distribute))}{' '}\n              {kind !== 'distribution' && <button type=\"button\" className=\"enlace\" onClick={() => choose('distribution')}>{t('eq.kind.distribution')} →</button>}</p>\n          )}\n        </section>\n      )}\n\n      {canWrite && status && (\n        <section className=\"tarjeta\">\n          <h3>{t('eq.newTitle')}</h3>\n          <label>{t('eq.kindLabel')}\n            <select value={kind} onChange={(e) => choose(e.target.value)}>\n              {KINDS.map((k) => <option key={k} value={k}>{t(`eq.kind.${k}`)}</option>)}\n            </select>\n          </label>\n          <p className=\"ayuda\">{t(`eq.help.${kind}`)}</p>\n\n          <div className=\"rejilla-tres\">\n            {kind === 'incorporation' && <>{field('capital', t('eq.f.capital'))}{field('paid_pct', t('eq.f.paid_pct'), { disabled: status.legal_form === 'sl' })}</>}\n            {kind === 'capital_increase' && <>{field('nominal', t('eq.f.nominal'))}{field('premium', t('eq.f.premium'))}{field('paid_pct', t('eq.f.paid_pct'), { disabled: status.legal_form === 'sl' })}</>}\n            {kind === 'reserves_to_capital' && <>{field('amount', t('eq.f.amount'))}\n              <label>{t('eq.f.source')}\n                <select value={form.source} onChange={(e) => setForm({ ...form, source: e.target.value })}>\n                  <option value=\"113\">113 · {t('eq.account.113')}</option><option value=\"110\">110 · {t('eq.account.110')}</option>\n                </select>\n              </label></>}\n            {kind === 'call' && <>{field('amount', t('eq.f.amount'))}\n              <label className=\"opcion\"><input type=\"checkbox\" checked={form.paid} onChange={(e) => setForm({ ...form, paid: e.target.checked })} /> {t('eq.f.paid')}</label></>}\n            {kind === 'distribution' && <>{field('dividend', t('eq.f.dividend'), { placeholder: m(status.interim_dividend) })}\n              {field('legal_reserve', t('eq.f.legal_reserve'), { placeholder: prev?.legal_reserve_min != null ? m(prev.legal_reserve_min) : '' })}</>}\n            {kind === 'interim_dividend' && <>{field('amount', t('eq.f.amount'))}{field('estimated_tax', t('eq.f.estimated_tax'), { placeholder: prev ? m(prev.estimated_tax) : '' })}</>}\n            {kind === 'dividend_payment' && <>{field('amount', t('eq.f.amount'), { placeholder: m(status.dividend_payable) })}\n              <label className=\"opcion\"><input type=\"checkbox\" checked={form.withholding} onChange={(e) => setForm({ ...form, withholding: e.target.checked })} /> {t('eq.f.withholding')}</label>\n              {!form.withholding && <label>{t('eq.f.no_withholding_reason')}\n                <input maxLength={200} value={form.no_withholding_reason} placeholder={t('eq.f.reasonPlaceholder')} onChange={(e) => setForm({ ...form, no_withholding_reason: e.target.value })} /></label>}</>}\n            {(kind === 'loss_offset' || kind === 'capital_reduction') && field('amount', t('eq.f.amount'))}\n          </div>\n\n          {kind === 'distribution' && prev && Number(prev.result) !== 0 && (\n            <div className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={t('eq.distTitle')}>\n              <table className=\"casillas\">\n                <caption className=\"oculto\">{t('eq.distTitle')}</caption>\n                <tbody>\n                  <tr><td>{t('eq.d.result')}</td><td className=\"num\">{m(prev.result)}</td></tr>\n                  {Number(prev.offset_losses) > 0 && <tr><td>{t('eq.d.offset')}</td><td className=\"num\">− {m(prev.offset_losses)}</td></tr>}\n                  {prev.result > 0 && <tr><td>{t('eq.d.legal')}<small className=\"articulo\"> · {t(prev.low_capital_sl ? 'eq.d.legalRuleLow' : 'eq.d.legalRule')}</small></td><td className=\"num\">− {m(prev.legal_reserve)}</td></tr>}\n                  {prev.result > 0 && <tr className=\"total\"><td>{t('eq.d.available')}</td><td className=\"num\">{m(prev.available)}</td></tr>}\n                  {prev.result > 0 && <tr><td>{t('eq.d.dividend')}{Number(prev.interim) > 0 && <small className=\"articulo\"> · {t('eq.d.interimPart').replace('{m}', m(prev.interim))}</small>}</td><td className=\"num\">− {m(prev.dividend)}</td></tr>}\n                  {prev.result > 0 && <tr className=\"total\"><td>{t('eq.d.voluntary')}</td><td className=\"num\">{m(prev.voluntary)}</td></tr>}\n                  <tr><td>{t('eq.d.netWorth')}<small className=\"articulo\"> · LSC art. 273</small></td><td className=\"num\">{m(prev.net_worth_after)} {prev.result > 0 && Number(prev.dividend) > 0 && (prev.net_worth_after >= prev.capital ? '≥' : '<')} {prev.result > 0 && Number(prev.dividend) > 0 && m(prev.capital)}</td></tr>\n                </tbody>\n              </table>\n            </div>\n          )}\n          {kind === 'interim_dividend' && prev && (\n            <div className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={t('eq.intTitle')}>\n              <table className=\"casillas\">\n                <caption className=\"oculto\">{t('eq.intTitle')}</caption>\n                <tbody>\n                  <tr><td>{t('eq.i.result')}</td><td className=\"num\">{m(prev.result_since_close)}</td></tr>\n                  {Number(prev.prior_losses) > 0 && <tr><td>{t('eq.i.losses')}</td><td className=\"num\">− {m(prev.prior_losses)}</td></tr>}\n                  <tr><td>{t('eq.i.tax')}</td><td className=\"num\">− {m(prev.estimated_tax)}</td></tr>\n                  <tr><td>{t('eq.i.legal')}</td><td className=\"num\">− {m(prev.legal_reserve)}</td></tr>\n                  {Number(prev.already_paid) > 0 && <tr><td>{t('eq.i.paid')}</td><td className=\"num\">− {m(prev.already_paid)}</td></tr>}\n                  <tr className=\"total\"><td>{t('eq.i.max')}<small className=\"articulo\"> · LSC art. 277</small></td><td className=\"num\">{m(prev.max)}</td></tr>\n                  <tr><td>{t('eq.i.cash')}</td><td className=\"num\">{m(prev.cash)}</td></tr>\n                </tbody>\n              </table>\n            </div>\n          )}\n          {warnings.length > 0 && (\n            <ul className=\"comprobaciones\">\n              {warnings.map((w, i) => <li key={i} className={w.code === 'losses_left' ? 'info' : 'warning'}><span className=\"icono\">{w.code === 'losses_left' ? 'ℹ' : '⚠'}</span> {warnText(w)}</li>)}\n            </ul>\n          )}\n\n          {entries.length > 0 && (\n            <>\n              <h4>{t('eq.entriesPreview')}</h4>\n              {entries.map((e) => (\n                <div key={e.key} className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={t(`eq.entry.${e.key}`)}>\n                  <table className=\"informe\">\n                    <caption>{t(`eq.entry.${e.key}`)}</caption>\n                    <thead><tr><th scope=\"col\">{t('account')}</th><th scope=\"col\" className=\"num\">{t('debit')}</th><th scope=\"col\" className=\"num\">{t('credit')}</th></tr></thead>\n                    <tbody>{e.lines.map((l) => (\n                      <tr key={l.account + l.debit}><td><span className=\"codigo\">{l.account}</span> {t(`eq.account.${l.account}`)}</td>\n                        <td className=\"num\">{l.debit ? m(l.debit) : ''}</td><td className=\"num\">{l.credit ? m(l.credit) : ''}</td></tr>))}</tbody>\n                  </table>\n                </div>\n              ))}\n              {!balanced(entries) && <p className=\"aviso\">{t('eq.unbalanced')}</p>}\n            </>\n          )}\n\n          {confirming !== 'post'\n            ? <button type=\"button\" disabled={busy || blocked} onClick={() => setConfirming('post')}>{t('eq.post')}</button>\n            : (\n              <div className=\"anular\" role=\"alertdialog\" aria-label={t('eq.confirmPost')}>\n                <p>{t('eq.confirmPost').replace('{k}', t(`eq.kind.${kind}`)).replace('{d}', shortDate(date))}</p>\n                <div className=\"fila\">\n                  <button type=\"button\" className=\"secundario\" onClick={() => setConfirming(null)}>{t('cancel')}</button>\n                  <button type=\"button\" disabled={busy} onClick={post}>{t('eq.post')}</button>\n                </div>\n              </div>\n            )}\n          {done && <p className=\"exito\" role=\"status\">✓ {t('eq.posted').replace('{c}', done.code).replace('{n}', (done.entry_nos ?? []).join(', '))}</p>}\n        </section>\n      )}\n\n      <section className=\"tarjeta\">\n        <h3>{t('eq.historyTitle')}</h3>\n        {ops.length === 0 ? <p className=\"ayuda\">{t('eq.historyNone')}</p> : (\n          <div className=\"tabla-ancha\" tabIndex={0} role=\"region\" aria-label={t('eq.historyTitle')}>\n            <table className=\"informe\">\n              <thead><tr><th scope=\"col\">{t('eq.col.code')}</th><th scope=\"col\">{t('eq.col.date')}</th><th scope=\"col\">{t('eq.col.kind')}</th><th scope=\"col\">{t('eq.col.entries')}</th><th scope=\"col\" aria-label={t('eq.undo')} /></tr></thead>\n              <tbody>{ops.map((o) => (\n                <tr key={o.id} className={o.status === 'cancelled' ? 'excluido' : ''}>\n                  <td><span className=\"codigo\">{o.code}</span></td>\n                  <td>{shortDate(o.op_date)}</td>\n                  <td>{t(`eq.kind.${o.kind}`)}{o.status === 'cancelled' && <span className=\"etiqueta etiqueta-texto\"> {t('eq.cancelled')}</span>}</td>\n                  <td>{(o.entry_ids ?? []).map(entryLink).filter(Boolean).reduce((acc, x) => (acc.length ? [...acc, ' · ', x] : [x]), [])}</td>\n                  <td>\n                    {canWrite && o.id === lastId && confirming !== o.id && <button type=\"button\" className=\"secundario\" disabled={busy} onClick={() => setConfirming(o.id)}>↩ {t('eq.undo')}</button>}\n                    {confirming === o.id && (\n                      <div className=\"anular\" role=\"alertdialog\" aria-label={t('eq.confirmUndo')}>\n                        <p>{t('eq.confirmUndo').replace('{c}', o.code)}</p>\n                        <div className=\"fila\">\n                          <button type=\"button\" className=\"secundario\" onClick={() => setConfirming(null)}>{t('cancel')}</button>\n                          <button type=\"button\" disabled={busy} onClick={() => undo(o.id)}>{t('eq.undo')}</button>\n                        </div>\n                      </div>\n                    )}\n                  </td>\n                </tr>))}</tbody>\n            </table>\n          </div>\n        )}\n        <p className=\"ayuda\">{t('eq.undoHelp')}</p>\n      </section>\n    </>\n  )\n}\n",
  "src/equity.js": "// OPERACIONES SOCIETARIAS (v0.42.0): cómo se enseña lo que hace la base de datos (0060 y 0061). Las reglas de la LSC y\n// los asientos los decide la base de datos; aquí se preparan los datos y se dibujan los mismos asientos antes de\n// contabilizar, para verlos (tests/equity.test.js los compara con los supuestos de referencia S1 a S6).\nimport { parseAmount } from './practice'\n\n// Las operaciones, en el orden de la vida de una sociedad\nexport const KINDS = ['incorporation', 'capital_increase', 'reserves_to_capital', 'call', 'distribution',\n  'interim_dividend', 'dividend_payment', 'loss_offset', 'capital_reduction']\n\n// Función de la base de datos de cada una (las de reparto y dividendo a cuenta tienen además su vista previa)\nexport const RPC = {\n  incorporation: 'equity_incorporation', capital_increase: 'equity_capital_increase', reserves_to_capital: 'equity_reserves_to_capital',\n  call: 'equity_call', distribution: 'equity_distribution', interim_dividend: 'equity_interim_dividend',\n  dividend_payment: 'equity_dividend_payment', loss_offset: 'equity_loss_offset', capital_reduction: 'equity_capital_reduction',\n}\nexport const PREVIEW_RPC = { distribution: 'equity_distribution_preview', interim_dividend: 'equity_interim_preview' }\n\n// Formulario vacío de cada operación\nexport const emptyForm = (kind, legalForm) => ({\n  incorporation: { capital: '', paid_pct: legalForm === 'sa' ? '25' : '100' },\n  capital_increase: { nominal: '', premium: '', paid_pct: '100' },\n  reserves_to_capital: { amount: '', source: '113' },\n  call: { amount: '', paid: true },\n  distribution: { dividend: '', legal_reserve: '' },\n  interim_dividend: { amount: '', estimated_tax: '' },\n  dividend_payment: { amount: '', withholding: true, no_withholding_reason: '' },\n  loss_offset: { amount: '' },\n  capital_reduction: { amount: '' },\n}[kind])\n\nconst num = (v) => (String(v ?? '').trim() === '' ? undefined : parseAmount(v))\nconst r2 = (v) => Math.round(v * 100) / 100\n\n// Lo que se manda a la base de datos: { company_id, date, …campos de la operación } (los vacíos no se mandan:\n// la base de datos pone su valor por defecto, p. ej. la reserva legal obligatoria o el impuesto estimado al 25 %)\nexport function payload(kind, form, companyId, date) {\n  const p = { company_id: companyId, date }\n  const set = (k, v) => { if (v !== undefined && v !== '') p[k] = v }\n  if (kind === 'incorporation') { set('capital', num(form.capital)); set('paid_pct', num(form.paid_pct)) }\n  if (kind === 'capital_increase') { set('nominal', num(form.nominal)); set('premium', num(form.premium)); set('paid_pct', num(form.paid_pct)) }\n  if (kind === 'reserves_to_capital') { set('amount', num(form.amount)); set('source', form.source) }\n  if (kind === 'call') { set('amount', num(form.amount)); p.paid = Boolean(form.paid) }\n  if (kind === 'distribution') { set('dividend', num(form.dividend)); set('legal_reserve', num(form.legal_reserve)) }\n  if (kind === 'interim_dividend') { set('amount', num(form.amount)); set('estimated_tax', num(form.estimated_tax)) }\n  if (kind === 'dividend_payment') {\n    set('amount', num(form.amount))\n    if (!form.withholding) set('no_withholding_reason', String(form.no_withholding_reason ?? '').trim())\n  }\n  if (kind === 'loss_offset' || kind === 'capital_reduction') set('amount', num(form.amount))\n  return p\n}\n\n// Reserva legal que toca (art. 274 LSC; SL de menos de 3.000 €: art. 4.2) — la misma regla que erp.equity_legal_reserve\nexport function legalReserve(form, capital, reserve, profit) {\n  if (profit <= 0) return 0\n  if (form === 'sl' && capital < 3000) return Math.max(0, Math.min(r2(profit * 0.2), 3000 - capital - reserve))\n  return Math.max(0, Math.min(r2(profit * 0.1), r2(capital * 0.2) - reserve))\n}\n\nconst L = (account, debit, credit) => ({ account, debit: r2(debit || 0), credit: r2(credit || 0) })\nconst clean = (lines) => lines.filter((l) => l.debit || l.credit)\n\n// Los asientos que hará «Contabilizar» (los mismos que la base de datos), con lo que hay en el formulario.\n//   status: erp.equity_status · prev: la vista previa del reparto o del dividendo a cuenta (de la base de datos)\n//   → [{ key, lines: [{ account, debit, credit }] }]   (vacío si aún faltan datos)\nexport function previewEntries(kind, form, status = {}, prev = null) {\n  const out = (key, lines) => ({ key, lines: clean(lines) })\n  if (kind === 'incorporation' || kind === 'capital_increase') {\n    const nominal = num(kind === 'incorporation' ? form.capital : form.nominal) ?? 0\n    const premium = kind === 'capital_increase' ? num(form.premium) ?? 0 : 0\n    if (nominal <= 0) return []\n    const pct = num(form.paid_pct) ?? 100\n    const paid = r2(nominal * pct / 100) + premium\n    return [\n      out('issue', [L('190', nominal + premium, 0), L('194', 0, nominal), L('110', 0, premium)]),\n      out('subscription', [L('572', paid, 0), L('1030', nominal + premium - paid, 0), L('190', 0, nominal + premium)]),\n      out('registration', [L('194', nominal, 0), L('100', 0, nominal)]),\n    ]\n  }\n  const amount = num(form.amount) ?? 0\n  if (kind === 'reserves_to_capital') return amount > 0 ? [out('reserves_to_capital', [L(form.source === '110' ? '110' : '113', amount, 0), L('100', 0, amount)])] : []\n  if (kind === 'call') {\n    if (amount <= 0) return []\n    const e = [out('call', [L('5580', amount, 0), L('1030', 0, amount)])]\n    return form.paid ? [...e, out('call_payment', [L('572', amount, 0), L('5580', 0, amount)])] : e\n  }\n  if (kind === 'distribution') {\n    if (!prev || !prev.result) return []\n    if (prev.result < 0) return [out('distribution', [L('121', -prev.result, 0), L('129', 0, -prev.result)])]\n    return [out('distribution', [L('129', prev.result, 0), L('121', 0, prev.offset_losses), L('112', 0, prev.legal_reserve),\n      L('557', 0, prev.interim), L('526', 0, prev.complementary), L('113', 0, prev.voluntary)])]\n  }\n  if (kind === 'interim_dividend') return amount > 0 ? [out('interim_dividend', [L('557', amount, 0), L('526', 0, amount)])] : []\n  if (kind === 'dividend_payment') {\n    const gross = num(form.amount) ?? Number(status.dividend_payable ?? 0)\n    if (gross <= 0) return []\n    const wh = form.withholding ? r2(gross * 0.19) : 0\n    return [out('dividend_payment', [L('526', gross, 0), L('47512', 0, wh), L('572', 0, gross - wh)])]\n  }\n  if (kind === 'loss_offset') return amount > 0 ? [out('loss_offset', [L('113', amount, 0), L('121', 0, amount)])] : []\n  if (kind === 'capital_reduction') return amount > 0 ? [out('capital_reduction', [L('100', amount, 0), L('121', 0, amount)])] : []\n  return []\n}\n\n// Filas del estado del patrimonio neto (signo: + suma, − resta del patrimonio neto)\nexport const STATUS_ROWS = [\n  ['capital', 1], ['uncalled', -1], ['premium', 1], ['legal_reserve', 1], ['voluntary_reserves', 1], ['prior_losses', -1],\n  ['result_to_distribute', 1], ['interim_dividend', -1],\n]\n\n// La operación que se puede deshacer: la última contabilizada (se deshacen de la última a la primera)\nexport function undoable(ops = []) {\n  return [...ops].filter((o) => o.status === 'posted').sort((a, b) => (a.code < b.code ? 1 : -1))[0]?.id ?? null\n}\n\n// ¿Cuadra cada asiento? (en céntimos)\nexport const balanced = (entries) => entries.every((e) =>\n  e.lines.reduce((s, l) => s + Math.round(l.debit * 100) - Math.round(l.credit * 100), 0) === 0)\n",
  "tests/equity.test.js": "import { describe, expect, it } from 'vitest'\nimport { balanced, legalReserve, payload, previewEntries, undoable } from '../src/equity'\nimport es from '../src/i18n/es.js'\nimport en from '../src/i18n/en.js'\n\nconst lines = (e) => e.lines.map((l) => `${l.account} ${l.debit ? 'D ' + l.debit : 'H ' + l.credit}`).join(' | ')\n\n// Las cifras son las de los supuestos de referencia (docs del proyecto: supuestos-v0.42.0.md; base de datos: fase 55)\ndescribe('operaciones societarias · asientos que se ven antes de contabilizar', () => {\n  it('S1 · constitución de una SA con el 25 % desembolsado', () => {\n    const e = previewEntries('incorporation', { capital: '60.000', paid_pct: '25' })\n    expect(e.map(lines)).toEqual(['190 D 60000 | 194 H 60000', '572 D 15000 | 1030 D 45000 | 190 H 60000', '194 D 60000 | 100 H 60000'])\n    expect(balanced(e)).toBe(true)\n  })\n  it('S2 · ampliación con prima: la prima, desembolsada entera', () => {\n    const e = previewEntries('capital_increase', { nominal: '100000', premium: '20000', paid_pct: '100' })\n    expect(e.map(lines)).toEqual(['190 D 120000 | 194 H 100000 | 110 H 20000', '572 D 120000 | 190 H 120000', '194 D 100000 | 100 H 100000'])\n  })\n  it('S1 · dividendo pasivo exigido y cobrado', () => {\n    expect(previewEntries('call', { amount: '22500', paid: true }).map(lines)).toEqual(['5580 D 22500 | 1030 H 22500', '572 D 22500 | 5580 H 22500'])\n    expect(previewEntries('call', { amount: '22500', paid: false })).toHaveLength(1)\n  })\n  it('S3 · reparto con la vista previa de la base de datos y pago con el 19 %', () => {\n    const prev = { result: 50000, offset_losses: 0, legal_reserve: 2000, interim: 0, complementary: 30000, voluntary: 18000 }\n    expect(previewEntries('distribution', {}, {}, prev).map(lines)).toEqual(['129 D 50000 | 112 H 2000 | 526 H 30000 | 113 H 18000'])\n    expect(previewEntries('dividend_payment', { amount: '20000', withholding: true }).map(lines)).toEqual(['526 D 20000 | 47512 H 3800 | 572 H 16200'])\n    expect(previewEntries('dividend_payment', { amount: '', withholding: false }, { dividend_payable: 10000 }).map(lines)).toEqual(['526 D 10000 | 572 H 10000'])\n  })\n  it('S4 y S5 · con dividendo a cuenta y con pérdidas', () => {\n    const prev = { result: 45000, offset_losses: 0, legal_reserve: 4500, interim: 20000, complementary: 10000, voluntary: 10500 }\n    expect(previewEntries('distribution', {}, {}, prev).map(lines)).toEqual(['129 D 45000 | 112 H 4500 | 557 H 20000 | 526 H 10000 | 113 H 10500'])\n    expect(previewEntries('distribution', {}, {}, { result: -20000 }).map(lines)).toEqual(['121 D 20000 | 129 H 20000'])\n    expect(previewEntries('interim_dividend', { amount: '20000' }).map(lines)).toEqual(['557 D 20000 | 526 H 20000'])\n  })\n  it('S6 · compensar con reservas y reducir el capital', () => {\n    expect(previewEntries('loss_offset', { amount: '5000' }).map(lines)).toEqual(['113 D 5000 | 121 H 5000'])\n    expect(previewEntries('capital_reduction', { amount: '18000' }).map(lines)).toEqual(['100 D 18000 | 121 H 18000'])\n  })\n  it('sin datos, sin asientos', () => {\n    expect(previewEntries('incorporation', { capital: '' })).toEqual([])\n    expect(previewEntries('distribution', {}, {}, null)).toEqual([])\n  })\n})\n\ndescribe('operaciones societarias · reglas y datos', () => {\n  it('reserva legal: 10 % hasta el 20 % del capital; SL de menos de 3.000 €, 20 % hasta 3.000 (misma regla que la base de datos)', () => {\n    expect(legalReserve('sl', 30000, 4000, 50000)).toBe(2000)\n    expect(legalReserve('sl', 30000, 0, 45000)).toBe(4500)\n    expect(legalReserve('sl', 1000, 0, 8000)).toBe(1600)\n    expect(legalReserve('sl', 1000, 1600, 8000)).toBe(400)\n    expect(legalReserve('sa', 60000, 12000, 100000)).toBe(0)\n    expect(legalReserve('sl', 30000, 0, -500)).toBe(0)\n  })\n  it('lo que se manda: importes en formato español y sin los campos vacíos (los pone la base de datos)', () => {\n    expect(payload('distribution', { dividend: '30.000', legal_reserve: '' }, 'c', '2027-05-20')).toEqual({ company_id: 'c', date: '2027-05-20', dividend: 30000 })\n    expect(payload('dividend_payment', { amount: '', withholding: false, no_withholding_reason: ' Exención art. 21 LIS ' }, 'c', 'd'))\n      .toEqual({ company_id: 'c', date: 'd', no_withholding_reason: 'Exención art. 21 LIS' })\n    expect(payload('incorporation', { capital: '60.000', paid_pct: '25' }, 'c', 'd')).toEqual({ company_id: 'c', date: 'd', capital: 60000, paid_pct: 25 })\n  })\n  it('solo se deshace la última contabilizada', () => {\n    expect(undoable([{ id: 'a', code: 'SOC-0001', status: 'posted' }, { id: 'b', code: 'SOC-0002', status: 'posted' }, { id: 'c', code: 'SOC-0003', status: 'cancelled' }])).toBe('b')\n    expect(undoable([])).toBe(null)\n  })\n  it('textos de cada operación, sus asientos y sus avisos en los dos idiomas', () => {\n    for (const d of [es, en]) {\n      for (const k of ['incorporation', 'capital_increase', 'reserves_to_capital', 'call', 'distribution', 'interim_dividend', 'dividend_payment', 'loss_offset', 'capital_reduction']) {\n        expect(d.eq.kind[k], k).toBeTruthy()\n      }\n      for (const w of ['no_result', 'dividend_with_loss', 'legal_reserve_below_min', 'dividend_below_interim', 'dividend_above_available', 'net_worth_below_capital', 'losses_left', 'interim_above_limit', 'interim_no_liquidity']) {\n        expect(d.eq.warn[w], w).toBeTruthy()\n      }\n      for (const a of ['100', '1030', '110', '112', '113', '121', '129', '190', '194', '526', '557', '5580', '572', '47512']) expect(d.eq.account[a], a).toBeTruthy()\n    }\n  })\n})\n\nimport { friendlyError } from '../src/errors'\nconst tr = (dict) => (k) => k.split('.').reduce((o, x) => (o == null ? undefined : o[x]), dict) ?? k\ndescribe('operaciones societarias · errores en lenguaje claro', () => {\n  const t = tr(es)\n  it('cada mensaje de la base de datos tiene su explicación y su pantalla', () => {\n    const cases = [\n      ['The company already has share capital: use a capital increase', /ya tiene capital/],\n      ['The share capital of an SA must be at least 60,000 (art. 4.3 LSC)', /60\\.000/],\n      ['In an SL the capital must be fully paid at incorporation (art. 78 LSC)', /SL/],\n      ['At least 25 % of the capital must be paid at incorporation (art. 79 LSC)', /25 %/],\n      ['There is no result to distribute on 2027-05-20: close the previous year first', /resultado del año anterior/],\n      ['The distribution is not valid: dividend_above_available', /Sociedades de Capital/],\n      ['The interim dividend is not valid: interim_above_limit (art. 277 LSC)', /277/],\n      ['Without withholding, say why (e.g. exemption of art. 21 LIS)', /motivo/],\n      ['Use the voluntary reserves first: capital cannot be reduced for losses while there are reserves (art. 322 LSC)', /reservas voluntarias/],\n      ['Undo the later equity operations first (from the last one)', /posteriores/],\n      ['This entry belongs to an equity operation: undo it from Equity operations', /operación societaria/],\n    ]\n    for (const [msg, re] of cases) {\n      const f = friendlyError(msg, t, 'es')\n      expect(f.title, msg).toMatch(re)\n      expect(f.technical, msg).toBe(msg)\n    }\n    expect(friendlyError('Not enough voluntary reserves (balance 1200.00)', t, 'es').hint).toMatch(/1\\.200,00/)\n    expect(friendlyError('There is no result to distribute on 2027-05-20: close the previous year first', t, 'es').to).toBe('closing')\n  })\n})\n"
}
